FIELD_VALIDATORS = {
    'name': [
        lambda x: x is not None, 'name is required',
        lambda x: len(x) >= 2, 'name must be at least 2 characters',
        lambda x: len(x) <= 100, 'name must be at most 100 characters',
    ],
    'email': [
        lambda x: x is not None, 'email is required',
        lambda x: '@' in x, 'email must contain @',
        lambda x: len(x) <= 254, 'email is too long',
    ],
    'age': [
        lambda x: x is not None, 'age is required',
        lambda x: isinstance(x, int), 'age must be an integer',
        lambda x: 0 <= x <= 150, 'age must be between 0 and 150',
    ],
    'role': [
        lambda x: x is not None, 'role is required',
        lambda x: x in ('admin', 'user', 'moderator'), 'role must be admin, user, or moderator',
    ],
}

def validate_field(field_name, field_value):
    errors = []
    for validator, error_message in FIELD_VALIDATORS.get(field_name, []):
        if not validator(field_value):
            errors.append(error_message)
    return errors

def validate_user_input(data):
    errors = []
    for field_name in FIELD_VALIDATORS:
        if field_name in data:
            errors.extend(validate_field(field_name, data[field_name]))
        else:
            errors.append(f'{field_name} is required')
    return errors
